    md_title: "மண்டி அடைவு",
    md_subtitle: "தற்போது அரசின் Agmarknet தரவுத்தொகுப்பிற்கு விலைகளைத் தெரிவிக்கும் அனைத்து மண்டிகள். ஒன்றைத் தேடி, அதைத் திறந்து அங்கு என்ன பயிர்கள் விற்கப்படுகின்றன, என்ன விலை கிடைக்கிறது எனப் பாருங்கள்.",
    md_total_registered: "மொத்தம் பதிவான மண்டிகள்",
