    mdet_mock_note: "அரசு API இந்த மண்டிக்கு எதுவும் தரவில்லை - கீழே விவசாயிகள் தெரிவித்த விலைகள் மட்டுமே (இருந்தால்) காட்டப்படுகின்றன.",
    mdet_none_title: "இன்று இந்த மண்டிக்கு எந்தப் பயிரும் தெரிவிக்கப்படவில்லை.",
    mdet_none_text: "மண்டிகள் தினமும் தெரிவிப்பதில்லை. நாளை மீண்டும் முயலுங்கள், அல்லது வேறு மண்டியைத் தேர்ந்தெடுங்கள்.",
    mdet_footnote: "அரசு என்பது data.gov.in இன் Agmarknet தரவுத்தொகுப்பின் மோடல் விலை. நமது விவசாயிகள் என்பது இந்தச் செயலியைப் பயன்படுத்தும் விவசாயிகள் இந்த மண்டியில் பெற்றதாகத் தெரிவித்த விலையின் சராசரி. கோடு என்றால் அந்த ஆதாரத்தில் அந்தப் பயிருக்குத் தரவு இல்லை.",
